public class MoneyTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("plus adds cents", new Money("USD", 375), new Money("USD", 250).plus(new Money("USD", 125)));
        check("plus keeps currency", new Money("EUR", 300), new Money("EUR", 100).plus(new Money("EUR", 200)));
        String outcome;
        try {
            new Money("USD", 100).plus(new Money("EUR", 100));
            outcome = "no exception";
        } catch (IllegalArgumentException e) {
            outcome = "IllegalArgumentException";
        }
        check("plus with mismatched currency", "IllegalArgumentException", outcome);
        check("pretty dollars and cents", "USD 12.34", new Money("USD", 1234).pretty());
        check("pretty pads cents", "EUR 0.05", new Money("EUR", 5).pretty());
        check("pretty whole amount", "GBP 1.00", new Money("GBP", 100).pretty());
        check("pretty zero", "USD 0.00", new Money("USD", 0).pretty());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

